def recall_at_k(ranked_ids: list[str], gold_id: str, k: int = 5) -> float:
    return 1.0 if gold_id in ranked_ids[:k] else 0.0


def evaluate(method: str, cases: list[dict]) -> dict:
    scores = [recall_at_k(c["ranked"], c["gold_doc_id"]) for c in cases]
    return {"method": method, "recall_at_5": sum(scores) / len(scores), "n": len(scores)}

